<template><PageShell :title="config.title" subtitle="Cadastros auxiliares da Central de Guias"><div class="panel"><form class="grid gap-3 md:grid-cols-3" @submit.prevent="save"><template v-for="field in config.fields" :key="field.key"><select v-if="field.options" v-model="form[field.key]" class="input" :required="field.required"><option value="">{{field.label}}</option><option v-for="option in field.options" :key="option.value" :value="option.value">{{option.label}}</option></select><input v-else v-model="form[field.key]" class="input" :placeholder="field.label" :required="field.required"></template><button class="btn">{{ editing ? 'Salvar alterações' : 'Adicionar' }}</button><button v-if="editing" type="button" class="input" @click="reset">Cancelar</button></form></div><div class="panel overflow-x-auto"><table class="table"><thead><tr><th>Nome / descrição</th><th>Tipo</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.name || item.full_name || `${item.code} — ${item.description}` }}</td><td>{{ enumLabel(item.authorization_type || item.type) }}</td><td>{{ item.active ? 'Ativo' : 'Inativo' }}</td><td class="space-x-2 text-right"><button class="link" @click="edit(item)">Editar</button><button class="link" @click="toggle(item)">{{ item.active ? 'Desativar' : 'Ativar' }}</button><label v-if="config.asset" class="link">{{config.asset.label}}<input class="hidden" type="file" :accept="config.asset.accept" @change="uploadAsset($event,item.id)"></label><button v-if="config.asset" class="link" @click="viewAsset(item.id)">Visualizar</button></td></tr></tbody></table></div></PageShell></template>
<script setup lang="ts">/* eslint-disable @typescript-eslint/no-explicit-any */import { computed, onMounted, reactive, ref, watch } from 'vue';import { useRoute } from 'vue-router';import api from '@/plugins/axios';import PageShell from '@/components/PageShell.vue';import { authorizationTypeLabels, professionalTypeLabels, procedureTypeLabels } from '@/utils/guideLabels';
type Item=Record<string,any>;const route=useRoute();const items=ref<Item[]>([]),editing=ref<number|null>(null),form=reactive<Item>({});const option=(map:Record<string,string>)=>Object.entries(map).map(([value,label])=>({value,label}));const enumLabels={...authorizationTypeLabels,...professionalTypeLabels,...procedureTypeLabels};const configs:Record<string,any>={insurance:{title:'Convênios',endpoint:'insurance-providers',fields:[{key:'name',label:'Nome',required:true},{key:'internal_code',label:'Código interno'},{key:'ans_registration',label:'Registro ANS'},{key:'authorization_type',label:'Tipo de liberação',required:true,options:option(authorizationTypeLabels)}],asset:{path:'insurance-providers',name:'logo',label:'Enviar logo',accept:'.png,.jpg,.jpeg'}},professionals:{title:'Profissionais',endpoint:'professionals',fields:[{key:'full_name',label:'Nome completo',required:true},{key:'type',label:'Tipo de profissional',required:true,options:option(professionalTypeLabels)},{key:'council',label:'Conselho',required:true},{key:'council_number',label:'Número',required:true},{key:'state',label:'UF',required:true},{key:'cbo',label:'CBO'}],asset:{path:'professionals',name:'signature',label:'Enviar assinatura',accept:'.png'}},procedures:{title:'Procedimentos',endpoint:'procedures',fields:[{key:'code',label:'Código',required:true},{key:'description',label:'Descrição',required:true},{key:'table_name',label:'Tabela'},{key:'type',label:'Tipo',required:true,options:option(procedureTypeLabels)}]}};const config=computed(()=>configs[String(route.meta.catalog)]);const enumLabel=(value:string)=>enumLabels[value as keyof typeof enumLabels]||value;async function load(){items.value=(await api.get(`/${config.value.endpoint}`)).data}function reset(){editing.value=null;Object.keys(form).forEach(k=>delete form[k]);form.active=true}async function save(){if(editing.value)await api.put(`/${config.value.endpoint}/${editing.value}`,form);else await api.post(`/${config.value.endpoint}`,form);reset();await load()}function edit(item:Item){reset();editing.value=item.id;Object.assign(form,item)}async function toggle(item:Item){await api.patch(`/${config.value.endpoint}/${item.id}/active`,{active:!item.active});await load()}async function uploadAsset(event:Event,id:number){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await api.post(`/${config.value.asset.path}/${id}/${config.value.asset.name}`,file,{headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)}})}async function viewAsset(id:number){const response=await api.get(`/${config.value.asset.path}/${id}/${config.value.asset.name}`,{responseType:'blob'});window.open(URL.createObjectURL(response.data),'_blank')}watch(()=>route.path,()=>{reset();load()});onMounted(()=>{reset();load()});</script>
